package com.travelbird.savedroute.controller;
import com.travelbird.auth.security.AuthenticatedUser;import com.travelbird.savedroute.service.AiPreviewSavedRouteService;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users/me/saved-routes/ai-previews") public class AiPreviewSavedRouteController{private final AiPreviewSavedRouteService service;public AiPreviewSavedRouteController(AiPreviewSavedRouteService s){service=s;}@PutMapping("/{previewId}")public ResponseEntity<Void> save(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long previewId){service.save(u.userId(),previewId);return ResponseEntity.noContent().build();}@DeleteMapping("/{previewId}")public ResponseEntity<Void> cancel(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long previewId){service.cancel(u.userId(),previewId);return ResponseEntity.noContent().build();}}
